2 17:13:24','2022-11-04',1),(101,32,'RoR','Riders of Rohan',4,32,'2022-03-12 17:14:09','2022-03-12 17:14:09','2022-11-04',1),(102,30,'MotR','ALeP - Mustering of the Rohirrim',5,11,'2022-06-13 09:19:06','2022-06-13 09:19:06','2022-06-13',0),(103,30,'BitI','ALeP - Blood in the Isen',6,10,'2022-09-09 12:49:12','2022-09-09 12:49:12','2022-09-09',0),(104,33,'AACE','Angmar Awakened Campaign Expansion',1,29,'2022-09-16 12:50:24','2022-09-16 12:54:24','2015-12-18',0),(105,15,'TNaA','ALeP - The Nine are Abroad',92,1,'2022-10-18 09:28:14','2025-10-01 08:11:59','2022-10-18',0),(107,15,'TSoEr','ALeP - The Siege of Erebor',93,3,'2023-09-06 12:35:35','2023-09-06 12:36:49','2023-09-06',0),(108,34,'TSR','ALeP - The Shire\'s Reckoning',1,22,'2024-02-29 15:48:34','2024-02-29 15:52:28','2024-02-29',0),(109,35,'DCCE','Dream-chaser Campaign Expansion',1,60,'2024-08-20 13:31:53','2024-08-20 13:31:53','2024-08-14',0),(110,36,'EMCE','Ered Mithrin Campaign Expansion',1,60,'2024-08-20 18:43:08','2024-08-20 18:43:08','2024-08-14',0),(111,15,'THo','ALeP - The Hobbit',94,21,'2024-11-07 17:26:08','2024-11-07 18:22:15','2024-11-07',0),(112,37,'SNiB','ALeP - Strange News in Bree',1,11,'2025-01-30 13:00:15','2025-06-30 15:06:44','2025-01-30',0),(113,37,'FitD','ALeP - Fangs in the Dark',2,14,'2025-06-30 15:05:42','2025-07-01 15:17:34','2025-06-30',0),(114,15,'TMoG','ALeP - The Mirror of Galadriel',95,17,'2025-11-04 19:23:45','2025-11-04 19:23:45','2025-11-04',0),(115,37,'TBP','ALeP - The Brandywine Pursuit',3,11,'2026-03-25 16:18:09','2026-03-25 16:18:09','2026-03-25',0);
